-- ============================================
-- LUMA — Enrichissement du 3e scénario long de Londres
-- ============================================

update scenarios set content = '{"characters": {"organizer": "l''organisateur local", "vendor": "un vendeur", "local": "un habitant du quartier"}, "start_node": "n1", "nodes": {"n1": {"speaker": "organizer", "text": "Welcome to the neighborhood festival! We''ve got food stalls, live music, and local crafts today.", "text_fr": "Bienvenue au festival de quartier ! On a des stands de nourriture, de la musique live, et de l''artisanat local aujourd''hui.", "choices": [{"text": "Let''s start with the food stalls, I''m starving.", "next": "n2"}, {"text": "I''d love to check out the live music first.", "next": "n2b"}]}, "n2": {"speaker": "vendor", "text": "Try our famous meat pies, a local specialty!", "text_fr": "Essayez nos fameuses tourtes à la viande, une spécialité locale !", "choices": [{"text": "Sounds great, I''ll take one.", "next": "n3"}]}, "n2b": {"speaker": "organizer", "text": "The main stage act starts in ten minutes, perfect timing!", "text_fr": "Le groupe principal commence dans dix minutes, timing parfait !", "choices": [{"text": "Let''s grab a good spot then.", "next": "n3b"}]}, "n3": {"speaker": "local", "text": "First time at this festival? You picked a great year, honestly.", "text_fr": "Première fois à ce festival ? Vous avez choisi une belle année, honnêtement.", "choices": [{"text": "It is, what makes this year special?", "next": "n4"}]}, "n3b": {"speaker": "local", "text": "(sitting nearby) This band is a local favorite, you''re in for a treat.", "text_fr": "(assis à côté) Ce groupe est un favori local, vous allez adorer.", "choices": [{"text": "I''m excited to hear them then.", "next": "n4b"}]}, "n4": {"speaker": "local", "text": "They''ve expanded the craft market this year — some incredible local artists.", "text_fr": "Ils ont agrandi le marché artisanal cette année — des artistes locaux incroyables.", "choices": [{"text": "Let''s check that out after the food.", "next": "n5"}]}, "n4b": {"speaker": "local", "text": "(the music starts, and it''s genuinely wonderful) See? Told you.", "text_fr": "(la musique commence, et c''est vraiment magnifique) Vous voyez ? Je vous l''avais dit.", "choices": [{"text": "You were absolutely right, this is amazing.", "next": "n5b"}]}, "n5": {"speaker": "vendor", "text": "(at the craft market) This handmade jewelry is one of a kind.", "text_fr": "(au marché artisanal) Ces bijoux faits main sont uniques en leur genre.", "choices": [{"text": "It''s beautiful, I''d love to buy a piece.", "next": "n6"}]}, "n5b": {"speaker": "organizer", "text": "Glad you''re enjoying it! There''s also a craft market if you want to explore more.", "text_fr": "Content que ça vous plaise ! Il y a aussi un marché artisanal si vous voulez explorer davantage.", "choices": [{"text": "Let''s check that out too.", "next": "n6"}]}, "n6": {"speaker": "organizer", "text": "As the sun sets, we''re closing with a community sing-along — want to join?", "text_fr": "Au coucher du soleil, on termine avec un chant communautaire — vous voulez vous joindre ?", "choices": [{"text": "Absolutely, this feels like the perfect way to end the day.", "next": "end_full"}, {"text": "I''ll watch and soak it all in instead.", "next": "end_observer"}]}, "end_full": {"speaker": "organizer", "text": "This is exactly what community is about. Thank you for being part of it today.", "text_fr": "C''est exactement ça, l''esprit de communauté. Merci d''en avoir fait partie aujourd''hui.", "end": true, "ending_label": "Événement local vécu pleinement, de bout en bout 🎪"}, "end_observer": {"speaker": "organizer", "text": "That''s just as meaningful — thank you for being here with us today.", "text_fr": "C''est tout aussi précieux — merci d''avoir été là avec nous aujourd''hui.", "end": true, "ending_label": "Belle immersion dans la culture locale 🎶"}}}'::jsonb, is_playable = true
where title = 'Un événement local (marché, festival de quartier) à vivre de bout en bout'
  and theme_id = (select id from scenario_themes where position = 15 and language_id = (select id from languages where code = 'en'));
